    PieceJointeFactureController_ajouter: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                id: number;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "multipart/form-data": {
                    /**
                     * Format: binary
                     * @description PDF, JPEG ou PNG (10 Mo maximum).
                     */
                    fichier: string;
                };
            };
        };
        responses: {
            /** @description Pièce jointe créée. */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        id?: number;
                        nomFichier?: string | null;
                        /** @example application/pdf */
                        typeFichier?: string;
                        tailleOctets?: number;
                        /** Format: date-time */
                        createdAt?: string;
                        ajoutePar?: {
                            id?: number;
                            nom?: string;
                        } | null;
                    };
                };
            };
            /** @description Fichier manquant ou multipart invalide. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Facture supprimée ou quota atteint. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Fichier supérieur à 10 Mo. */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Signature ou type MIME invalide. */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
